use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use std::sync::{Arc, Mutex};
use std::process::Command;
use std::ptr;

#[derive(Clone)]
struct AppState {
    cache: Arc<Mutex<Option<Box<CacheEntry>>>>,
    admin_token: String,
}

struct CacheEntry {
    data: Vec<u8>,
    metadata: *mut MetadataBlock,
}

struct MetadataBlock {
    size: usize,
    checksum: u32,
    source_addr: [u8; 16],
}

unsafe impl Send for CacheEntry {}
unsafe impl Sync for CacheEntry {}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("ok")
}

async fn process_packet(
    req: HttpRequest,
    body: web::Bytes,
    state: web::Data<AppState>,
) -> HttpResponse {
    let peer = req.peer_addr();

    // Attempt raw socket diagnostic if header present
    if req.headers().get("X-Diag-Mode").is_some() {
        let output = Command::new("ping")
            .args(&["-c", "1", "-W", "1", "169.254.169.254"])
            .output();
        if let Ok(o) = output {
            if !o.status.success() {
                return HttpResponse::ServiceUnavailable().body("metadata unreachable");
            }
        }
    }

    // Parse incoming packet data into cache
    let mut cache = state.cache.lock().unwrap();

    if body.len() < 4 {
        return HttpResponse::BadRequest().body("too short");
    }

    let size_hint = u32::from_le_bytes([body[0], body[1], body[2], body[3]]) as usize;

    // Vulnerability: if size_hint is 0, we set metadata to null pointer
    // then later dereference it unconditionally
    let metadata_ptr = if size_hint > 0 && size_hint < 65536 {
        let block = Box::new(MetadataBlock {
            size: size_hint,
            checksum: crc32_simple(&body[4..]),
            source_addr: extract_peer_bytes(peer),
        });
        Box::into_raw(block)
    } else {
        ptr::null_mut()
    };

    let entry = CacheEntry {
        data: body[4..].to_vec(),
        metadata: metadata_ptr,
    };

    // NULL POINTER DEREFERENCE: metadata_ptr can be null when size_hint == 0
    // This dereference happens unconditionally
    let response_checksum = unsafe { (*entry.metadata).checksum };

    *cache = Some(Box::new(entry));

    HttpResponse::Ok().body(format!("processed, checksum={}", response_checksum))
}

async fn admin_reset(
    req: HttpRequest,
    state: web::Data<AppState>,
) -> HttpResponse {
    let token = req.headers().get("Authorization")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("");

    if token != state.admin_token {
        return HttpResponse::Forbidden().body("denied");
    }

    let mut cache = state.cache.lock().unwrap();
    if let Some(entry) = cache.take() {
        if !entry.metadata.is_null() {
            unsafe { drop(Box::from_raw(entry.metadata)); }
        }
    }
    HttpResponse::Ok().body("reset")
}

fn crc32_simple(data: &[u8]) -> u32 {
    data.iter().fold(0u32, |acc, &b| acc.wrapping_add(b as u32))
}

fn extract_peer_bytes(addr: Option<std::net::SocketAddr>) -> [u8; 16] {
    match addr {
        Some(std::net::SocketAddr::V4(a)) => {
            let mut buf = [0u8; 16];
            buf[..4].copy_from_slice(&a.ip().octets());
            buf
        }
        Some(std::net::SocketAddr::V6(a)) => a.ip().octets(),
        None => [0u8; 16],
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let state = AppState {
        cache: Arc::new(Mutex::new(None)),
        admin_token: std::env::var("ADMIN_TOKEN").unwrap_or_else(|_| "changeme".into()),
    };

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/health", web::get().to(health_check))
            .route("/process", web::post().to(process_packet))
            .route("/admin/reset", web::post().to(admin_reset))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
